import{_ as n,a0 as d,w as p,s as u,ao as a,I as r,x as e,a1 as o,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const A=JSON.parse('{"title":"如何在 Ubuntu 中錄製流媒體音頻 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Ubuntu 中錄製流媒體音頻 | LCTT (202212) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Ubuntu 中錄製流媒體音頻 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Ubuntu 中錄製流媒體音頻 | LCTT (202212) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202212/20220810 How to Record Streaming Audio in Ubuntu and other Linux Distributions","title":"如何在 Ubuntu 中錄製流媒體音頻","tag":"202212","desc":""},"relativePath":"202212/20220810 How to Record Streaming Audio in Ubuntu and other Linux Distributions.md","filePath":"[post].md"}'),l={name:"202212/20220810 How to Record Streaming Audio in Ubuntu and other Linux Distributions.md"};function g(h,t,b,m,f,k){const i=d("Link");return p(),u("div",null,[t[33]||(t[33]=a('<h1 id="如何在-ubuntu-中錄製流媒體音頻" tabindex="-1">如何在 Ubuntu 中錄製流媒體音頻 <a class="header-anchor" href="#如何在-ubuntu-中錄製流媒體音頻" aria-label="Permalink to “如何在 Ubuntu 中錄製流媒體音頻”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202212/25/154829ol11lp47i8o6222c.jpg" alt=""></p><blockquote><p>如何在 Ubuntu 和其他 Linux 發行版中錄製音頻？</p></blockquote><p>如果你想通過計算機的麥克風錄製語音，可以使用 GNOME <ruby>錄音機<rt>Sound Recorder</rt></ruby> 或 Audacity。</p><p>使用 GNOME 錄音機很簡單，但它功能不足。Audacity 最初可能會讓人無從入手，但它有很多專業級錄音的功能。不過，在本教程中，我不打算詳細討論這個問題。</p><p>GNOME 錄音機能與麥克風配合使用。還有一個叫做 Audio recorder 的工具，除了麥克風輸入，你可以使用它來錄製流媒體音樂（來自 Sptify、YouTube、互聯網廣播、Skype 和其他大多數來源）。</p><p>總而言之，我將向你展示以下步驟：</p><ul><li>使用 GNOME 錄音機錄製聲音</li><li>使用 Audio Recorder 錄製流音頻</li></ul><h3 id="使用-gnome-錄音機從麥克風錄製音頻" tabindex="-1">使用 GNOME 錄音機從麥克風錄製音頻 <a class="header-anchor" href="#使用-gnome-錄音機從麥克風錄製音頻" aria-label="Permalink to “使用 GNOME 錄音機從麥克風錄製音頻”">​</a></h3><p>GNOME 桌面環境有很多有用的應用程序，錄音機就是其中之一。</p>',10)),r("p",null,[t[1]||(t[1]=e("你可以從 Ubuntu 軟件中心安裝 ",-1)),o(i,{href:"https://wiki.gnome.org/Apps/SoundRecorder"},{default:s(()=>[...t[0]||(t[0]=[e("錄音機",-1)])]),_:1}),t[2]||(t[2]=e("。",-1))]),t[34]||(t[34]=a('<p><img src="https://itsfoss.com/wp-content/uploads/2022/08/sound-recorder-ubuntu.png" alt="Sound Recorder can be installed from the Ubuntu Software Center"></p><p>或者，你可以在終端中使用此命令來安裝它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install gnome-sound-recorder</span></span></code></pre></div><p>安裝後，你可以在系統菜單中找到它，並從那裏啓動它。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/08/sound-recorder.png" alt="GNOME Sound Recorder"></p><p>在開始使用它之前，應確保在系統設置中選擇了正確的輸入源：</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/08/microphone-settings-ubuntu.png" alt="Ensure that you have chosen correct input in system settings"></p><p>打開錄音機，它將顯示如下界面：</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/08/using-sound-recorder-linux.png" alt="Hit the Record button to start audio recording"></p><p>點擊“<ruby>錄製<rt>Record</rt></ruby>”按鈕，它立即開始錄製音頻。錄製時，你可以選擇暫停、停止或取消錄製。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/08/sound-recording-with-sound-recorder.png" alt="Options while recording audio"></p><p>你的錄音將保存並可從應用程序界面本身獲得。單擊保存的錄音以突出顯示。</p><p>你可以回放或刪除該錄音。你可以通過單擊“保存/下載”按鈕選擇將其保存到其他位置。你也可以使用“編輯”按鈕重命名該錄音。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/08/sound-recorder-interface.png" alt="Saved recordings"></p><p>這很方便，對吧？你可以選擇以 <code>MP3</code>、<code>FLAC</code> 和多種格式錄製。</p><h4 id="刪除-gnome-錄音機" tabindex="-1">刪除 GNOME 錄音機 <a class="header-anchor" href="#刪除-gnome-錄音機" aria-label="Permalink to “刪除 GNOME 錄音機”">​</a></h4><p>不喜歡它或發現它缺乏功能？</p><p>你可以從 Ubuntu 軟件中心刪除 GNOME 錄音機，或使用以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt remove gnome-sound-recorder</span></span></code></pre></div><p>GNOME 錄音機應用功能有限，它只從麥克風錄製，在某些情況下這不是你想要的。</p><p>想像一下你想錄制 Skype 通話或在應用程序或網絡瀏覽器中播放的內容？在這種情況下，漂亮的 Audio Recorder 會有所幫助。</p><h3 id="使用-audio-recorder-來錄製流媒體音頻" tabindex="-1">使用 Audio Recorder 來錄製流媒體音頻 <a class="header-anchor" href="#使用-audio-recorder-來錄製流媒體音頻" aria-label="Permalink to “使用 Audio Recorder 來錄製流媒體音頻”">​</a></h3>',22)),r("p",null,[t[4]||(t[4]=e("你可以使用 ",-1)),o(i,{href:"https://launchpad.net/~audio-recorder/+archive/ubuntu/ppa"},{default:s(()=>[...t[3]||(t[3]=[e("官方 PPA",-1)])]),_:1}),t[5]||(t[5]=e(" 在 Ubuntu 和 LinuxMint 中安裝 ",-1)),t[6]||(t[6]=r("code",null,"Audio Recorder",-1)),t[7]||(t[7]=e("。在終端中依次使用以下命令：",-1))]),t[35]||(t[35]=a(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-add-repository ppa:audio-recorder/ppa</span></span>
<span class="line"><span>sudo apt update</span></span>
<span class="line"><span>sudo apt install audio-recorder</span></span></code></pre></div>`,1)),r("p",null,[t[9]||(t[9]=e("或者，你可以從 ",-1)),o(i,{href:"https://launchpad.net/audio-recorder"},{default:s(()=>[...t[8]||(t[8]=[e("啓動台",-1)])]),_:1}),t[10]||(t[10]=e(" 下載源代碼。安裝後，你可以從“",-1)),t[11]||(t[11]=r("ruby",null,[e("活動概述"),r("rt",null,"Activity Overview")],-1)),t[12]||(t[12]=e("”裏啓動應用程序：",-1))]),t[36]||(t[36]=a('<p><img src="https://itsfoss.com/wp-content/uploads/2022/08/audio-recorder-in-overview.png" alt="Audio Recorder"></p><h4 id="記錄不同來源的各種聲音" tabindex="-1">記錄不同來源的各種聲音 <a class="header-anchor" href="#記錄不同來源的各種聲音" aria-label="Permalink to “記錄不同來源的各種聲音”">​</a></h4><p>Audio Recorder 記錄計算機產生的各種聲音。</p><p>它記錄通過系統聲卡、麥克風、瀏覽器、網絡攝像頭等播放的音頻。</p><p>換句話説，即使你的系統打噴嚏，它也會記錄（如果你想記錄的話）。它允許你選擇錄製設備，如網絡攝像頭、麥克風、Skype 等。</p><p>要錄製流媒體音樂，請選擇適當的源。例如，如果你正在 Rhythmbox 中播放流媒體廣播，請選擇 Rythmbox。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/08/audio-recorder-audio-settings.png" alt="Audio-Recorder Audio Settings"></p><h4 id="在你方便的時候錄製" tabindex="-1">在你方便的時候錄製 <a class="header-anchor" href="#在你方便的時候錄製" aria-label="Permalink to “在你方便的時候錄製”">​</a></h4><p>Audio Recorder 還提供了設置計時器的選項。你可以在給定的時鐘時間或預定義的間隔開始、停止或暫停錄製。你還可以設置錄製文件大小的限制。</p><p>此外，你可以在沒有音頻（或聲音很低）時暫停（和停止），並在聲音恢復時繼續。</p><p>你所要做的就是編輯計時器面板中的文本。註釋掉你不想應用的“規則”，並根據你的要求編輯這些規則。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/08/audio-recorder-timer-settings.png" alt="Audio-recorder Timer Settings"></p><p>它提供了其他設置，如登錄時自動啓動、顯示托盤圖標和其他記錄設置。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/08/audio-recorder-additional-settings.png" alt="Audio-recorder Additional Settings"></p><h4 id="以各種文件格式保存錄制的音樂文件" tabindex="-1">以各種文件格式保存錄制的音樂文件 <a class="header-anchor" href="#以各種文件格式保存錄制的音樂文件" aria-label="Permalink to “以各種文件格式保存錄制的音樂文件”">​</a></h4><p>另一個寶藏。你可以將錄製的文件保存為你喜愛的文件格式。支持的文件格式有 OGG 音頻、Flac、MP3、SPX 和 WAV。我錄音時更喜歡用 MP3 格式。</p><p>錄製的文件存儲在 <code>~/Audio</code> 中，即主目錄中的“音頻”文件夾中。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/08/audio-recorder-audio-formats.png" alt="Audio-recorder Audio Formats"></p><h4 id="audio-recorder-有多好" tabindex="-1">Audio Recorder 有多好？ <a class="header-anchor" href="#audio-recorder-有多好" aria-label="Permalink to “Audio Recorder 有多好？”">​</a></h4>',19)),r("p",null,[t[14]||(t[14]=e("我在 Ubuntu 中使用 Audio Recorder ",-1)),o(i,{href:"https://itsfoss.com/youtube-dl-audio-only/"},{default:s(()=>[...t[13]||(t[13]=[e("錄製 YouTube 上播放的音樂",-1)])]),_:1}),t[15]||(t[15]=e("。我用 MP3 格式保存了一段 2 分鐘的視頻，佔用了 934 KB 的空間。但我必須説，我沒想到錄製的音質會這麼好。老實説，我無法將它與 YouTube 上的原始歌曲區分開來。",-1))]),t[37]||(t[37]=a('<h4 id="刪除-audio-recorder" tabindex="-1">刪除 Audio Recorder <a class="header-anchor" href="#刪除-audio-recorder" aria-label="Permalink to “刪除 Audio Recorder”">​</a></h4><p>如果你不喜歡 Audio Recorder，可以使用以下命令將其刪除：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt remove audio-recorder</span></span></code></pre></div>',3)),r("p",null,[o(i,{href:"https://itsfoss.com/how-to-remove-or-delete-ppas-quick-tip/"},{default:s(()=>[...t[16]||(t[16]=[e("同時刪除 PPA",-1)])]),_:1}),t[17]||(t[17]=e(" 是個好主意：",-1))]),t[38]||(t[38]=a('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-add-repository -r ppa:audio-recorder/ppa</span></span></code></pre></div><h3 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to “結論”">​</a></h3><p>Linux 中可能還有其他幾種用於音頻錄製的工具。像 GNOME 一樣，其他桌面環境也可能有錄音應用程序。我知道深度操作系統肯定有一個。</p><p>GNOME 錄音機是一個不錯的工具，用於從麥克風錄製聲音。對於錄製各種來源的聲音，Audio Recorder 是一個不錯的選擇。</p><p>我希望這篇文章能滿足你的錄音需求。如果你有什麼建議，請告訴我。</p><hr>',6)),r("p",null,[t[19]||(t[19]=e("via: ",-1)),o(i,{href:"https://itsfoss.com/record-streaming-audio/"},{default:s(()=>[...t[18]||(t[18]=[e("https://itsfoss.com/record-streaming-audio/",-1)])]),_:1})]),r("p",null,[t[24]||(t[24]=e("作者：",-1)),o(i,{href:"https://itsfoss.com/"},{default:s(()=>[...t[20]||(t[20]=[e("Abhishek Prakash",-1)])]),_:1}),t[25]||(t[25]=e(" 選題：",-1)),o(i,{href:"https://github.com/lkxed"},{default:s(()=>[...t[21]||(t[21]=[e("lkxed",-1)])]),_:1}),t[26]||(t[26]=e(" 譯者：",-1)),o(i,{href:"https://github.com/FYJNEVERFOLLOWS"},{default:s(()=>[...t[22]||(t[22]=[e("FYJNEVERFOLLOWS",-1)])]),_:1}),t[27]||(t[27]=e(" 校對：",-1)),o(i,{href:"https://github.com/wxy"},{default:s(()=>[...t[23]||(t[23]=[e("wxy",-1)])]),_:1})]),r("p",null,[t[30]||(t[30]=e("本文由 ",-1)),o(i,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[28]||(t[28]=[e("LCTT",-1)])]),_:1}),t[31]||(t[31]=e(" 原創編譯，",-1)),o(i,{href:"https://linux.cn/"},{default:s(()=>[...t[29]||(t[29]=[e("Linux中國",-1)])]),_:1}),t[32]||(t[32]=e(" 榮譽推出",-1))])])}const x=n(l,[["render",g]]);export{A as __pageData,x as default};
